import os

final class Ledger {
    private let state = OSAllocatedUnfairLock(initialState: Int64(0))

    func transfer(cents: Int64) {
        state.withLock { balance in      // lock held for the closure only
            balance += cents
        }
    }
}

actor Ledger {
    private var balance: Int64 = 0

    func transfer(cents: Int64) {
        balance += cents          // actor isolation: serialized, no lock calls
    }
}

let ledger = Ledger()
await ledger.transfer(cents: 100)
